use clap::Parser;
use rxla_core::{Buffer, CacheLimits, Client, Compiler};
use rxla_models::flux2::{Flux2Config, flux2};
use rxla_nn::{Cx, Model, ModelInput};
use rxla_safetensors::SafeTensors;
use std::path::PathBuf;

type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;

#[derive(Parser)]
#[command(about = "Compare RXLA FLUX.2 with the official PyTorch implementation")]
struct Args {
    /// Trusted PJRT plugin shared library.
    plugin: PathBuf,
    /// weights.safetensors generated by benchmarks/flux2_oracle.py.
    weights: PathBuf,
    /// oracle.safetensors generated by benchmarks/flux2_oracle.py.
    oracle: PathBuf,
}

fn upload(client: &Client, checkpoint: &mut SafeTensors, name: &str) -> Result<Buffer> {
    let tensor = checkpoint.read_f32(name)?;
    Ok(client.buffer(&tensor.shape, &tensor.values)?)
}

fn run(args: Args) -> Result<()> {
    let client = unsafe { Client::load(args.plugin) }?;
    let config = Flux2Config::tiny();
    let model = Model::new(|cx: Cx, image, image_ids, timestep, context, context_ids| {
        flux2(
            cx,
            &image,
            &image_ids,
            &timestep,
            &context,
            &context_ids,
            &config,
        )
    })
    .inputs((
        ModelInput::new([1, 3, 8]),
        ModelInput::new([1, 3, 4]),
        ModelInput::new([1]),
        ModelInput::new([1, 2, 12]),
        ModelInput::new([1, 2, 4]),
    ))
    .trace()?;
    let mut weights = SafeTensors::open(args.weights)?;
    let parameters = weights.load_parameter_schema(&client, model.schema())?;
    let compiled = model.compile(&mut Compiler::new(client.clone(), CacheLimits::default()))?;
    let runner = compiled.bind_parameters(parameters.bindings())?;
    let mut oracle = SafeTensors::open(args.oracle)?;
    let image = upload(&client, &mut oracle, "image")?;
    let image_ids = upload(&client, &mut oracle, "image_ids")?;
    let timestep = upload(&client, &mut oracle, "timestep")?;
    let context = upload(&client, &mut oracle, "context")?;
    let context_ids = upload(&client, &mut oracle, "context_ids")?;
    let output: Buffer = runner.run((&image, &image_ids, &timestep, &context, &context_ids))?;
    let actual = output.to_vec::<f32>()?;
    let expected = oracle.read_f32("output")?.values;
    let mut max_absolute = 0.0_f32;
    let mut sum_absolute = 0.0_f64;
    for (&actual, &expected) in actual.iter().zip(&expected) {
        let error = (actual - expected).abs();
        max_absolute = max_absolute.max(error);
        sum_absolute += f64::from(error);
    }
    let mean_absolute = sum_absolute / actual.len() as f64;
    println!(
        "backend={} max_absolute={max_absolute:.9} mean_absolute={mean_absolute:.9} checksum={:.9}",
        client.info()?.platform,
        actual.iter().map(|&value| f64::from(value)).sum::<f64>(),
    );
    if max_absolute > 2e-4 {
        return Err(format!("FLUX.2 numerical mismatch: max absolute error {max_absolute}").into());
    }
    Ok(())
}

fn main() -> Result<()> {
    run(Args::parse())
}
